-- Loads the CRM tables into Postgres through the Galaxy `postgresql` catalog: paste
-- into the Galaxy query editor and run the statements in order. Alternative to
-- load_crm_postgres.sql for when you don't have psql access to the database.
--
-- Needs: a PostgreSQL catalog named `postgresql`, attached to your cluster, that
-- allows writes. To target a different catalog.schema, change CRM_TABLE_PREFIX
-- in scripts/generate_crm_data.py and re-run it rather than editing this file.
--
-- DROPS AND RECREATES postgresql.crm.crm_interactions and postgresql.crm.crm_digital_activity,
-- so re-running it doesn't duplicate rows.
--
-- Generated by scripts/generate_crm_data.py from seeds/*.csv -- don't edit by hand.

create schema if not exists postgresql.crm;

drop table if exists postgresql.crm.crm_interactions;

create table postgresql.crm.crm_interactions (
    interaction_id   bigint,
    customer_id      varchar(32),
    interaction_ts   timestamp(6),
    channel          varchar(16),
    reason           varchar(32),
    is_complaint     boolean,
    sentiment_score  decimal(4, 2)
);

drop table if exists postgresql.crm.crm_digital_activity;

create table postgresql.crm.crm_digital_activity (
    customer_id      varchar(32),
    activity_month   date,
    logins           integer,
    bill_pay_events  integer,
    app_rating       integer
);

